import {createHash,timingSafeEqual,createDecipheriv} from 'node:crypto';
// Authenticated encrypted bundle. No plaintext business assets are stored here.
// No public asset copy: every response passes this credential gate.
const BUNDLE = {"iv":"BTuoR9YnMJGqFl9y","tag":"sOg3jdKRYGDvlg8r05E0Yw==","data":""}; // END_BUNDLE
const hash=value=>createHash('sha256').update(value).digest();
export function createHandler(bundle){return function handler(req,res){
 res.setHeader('Cache-Control','private, no-store, max-age=0');
 res.setHeader('CDN-Cache-Control','no-store');
 res.setHeader('Vercel-CDN-Cache-Control','no-store');
 res.setHeader('Vary','Authorization');
 res.setHeader('X-Content-Type-Options','nosniff');
 res.setHeader('X-Robots-Tag','noindex, nofollow, noarchive');
 res.setHeader('Referrer-Policy','no-referrer');
 res.setHeader('Content-Security-Policy',"default-src 'none'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self'; connect-src 'none'; font-src 'none'; frame-ancestors 'none'; base-uri 'none'; form-action 'none'; object-src 'none'");
 const end=(status,text)=>{res.statusCode=status;res.setHeader('Content-Type','text/plain; charset=utf-8');res.end(text);};
 if(req.method!=='GET'){res.setHeader('Allow','GET');return end(405,'Method not allowed');}
 const user=process.env.VISION_ACCESS_USER,password=process.env.VISION_ACCESS_PASSWORD;
 if(!user||!password||user.includes(':'))return end(503,'Private workspace access is not configured.');
 const auth=req.headers?.authorization;
 const expected='Basic '+Buffer.from(user+':'+password,'utf8').toString('base64');
 if(typeof auth!=='string'||auth.length>4096||!timingSafeEqual(hash(auth),hash(expected))){res.setHeader('WWW-Authenticate','Basic realm="BuilderK Vision", charset="UTF-8"');return end(401,'Private workspace. Authentication required.');}
 // Exact allowlist only. Direct /api/vision requests use the same gate.
 const url=new URL(req.url||'/api/vision','https://builderk.com');
 if(url.searchParams.getAll('asset').length>1)return end(404,'Not found');
 const asset=req.query?.asset??url.searchParams.get('asset')??'process-interactive.html';
 const allowed=['process-interactive.html','process-interactive.css','process-interactive.js','process-modules.js','process-map-v1.png'];
 if(typeof asset!=='string'||!allowed.includes(asset))return end(404,'Not found');
 let ASSETS;
 try{
  const secret=process.env.VISION_BUNDLE_KEY;
  if(typeof secret!=='string'||!/^[A-Za-z0-9+/]{43}=$/.test(secret))throw Error('configuration');
  const key=Buffer.from(secret,'base64');if(key.length!==32)throw Error('configuration');
  const decipher=createDecipheriv('aes-256-gcm',key,Buffer.from(bundle.iv,'base64'));
  decipher.setAAD(Buffer.from('builderk-vision-v1'));
  decipher.setAuthTag(Buffer.from(bundle.tag,'base64'));
  const plaintext=Buffer.concat([decipher.update(Buffer.from(bundle.data,'base64')),decipher.final()]);
  ASSETS=JSON.parse(plaintext.toString('utf8'));
  if(!ASSETS||Object.keys(ASSETS).length!==5||!allowed.every(name=>typeof ASSETS[name]?.base64==='string'&&typeof ASSETS[name]?.type==='string'))throw Error('bundle');
 }catch{return end(503,'Private workspace content is unavailable.');}
 if(typeof asset!=='string'||!Object.hasOwn(ASSETS,asset))return end(404,'Not found');
 const entry=ASSETS[asset];res.statusCode=200;res.setHeader('Content-Type',entry.type);res.end(Buffer.from(entry.base64,'base64'));
};}
export default createHandler(BUNDLE);
